    encoding: 'utf8', timeout: 60000, env: { ...process.env, NODE_BIN: process.execPath.replace(/\\/g, '/'),
      FORGE_SCRIPTS_DIR: path.join(root, 'scripts').replace(/\\/g, '/'), ...env } });
