  const run = (owner, env) => runBash(`${script}\necho continued`, { WORKING_DIR: owner.replace(/\\/g, '/'), TASK_ID: T06_TASK, LINKED_UNIT: `plan-slice/${T06_TASK}`, ...env });
  const free = t06Owner('admit');
